mapper.select:
select u.id, u.username, u.email, u.dept_id, d.dept_name, u.status, u.create_time from user u left join dept d on u.dept_id = d.id and d.deleted = 0 where u.deleted = 0
and u.username like concat('%', #{query.username}, '%')
and u.email like concat('%', #{query.email}, '%')
and u.status = #{query.status}
and u.dept_id = #{query.deptId}
order by u.create_time desc
